import {questions,butanoic,butanenitrile} from './exam-data.mjs';
import {clone,change,compareGraphs,checkArrowSet,checkReagents,bondId} from './chem-core.mjs';
import {drawGraph,moleculeSVG,ElectronCanvas} from './chem-svg.mjs';
import {t,pick,escapeHTML as esc} from './locale.mjs';
export const visualQuestions=questions;
const chips={Cl:'Cl',Br:'Br',OH:'OH',NH2:'NH2',CH2OH:'CH2OH',CHO:'CHO',COOH:'COOH',CN:'C≡N',CONH2:'CONH2','CO2, dry THF':'CO2 · dry THF','H3O+ / water':'H3O+ · H2O','H2O':'H2O','NaBH4':'NaBH4','NaCN, DMF':'NaCN · DMF','hot aqueous HCl, reflux':'HCl(aq) · Δ','NaOH, water, reflux':'NaOH(aq) · Δ','HCl, acidify':'HCl · H+','LiAlH4, dry THF':'LiAlH4 · dry THF'};
const pieceLabel=p=>(chips[p]||p).replace(/dry/g,pick('dry','无水','anhydre'));
export class VisualLab{
 constructor(container,{question,record,translate,onSave,onBack,onRead}){Object.assign(this,{container,q:question,L:translate,onSave,onBack,onRead});this.data=clone(record?.data||{index:0,steps:{}});this.needsReview=!!record?.needsReview;this.completed=!!record?.completed;this.history=[];this.activePiece=null;this.feedback=null;this.hint=false;this.reveal=false;this.handle=e=>this.click(e);container.addEventListener('click',this.handle);container.addEventListener('keydown',e=>{if(this.q.kind!=='mechanism'&&(e.key==='Enter'||e.key===' ')){const anchor=e.target.closest('[data-anchor]');if(anchor){e.preventDefault();this.apply(anchor.dataset.anchor)}}});container.addEventListener('pointerdown',e=>this.dragStart(e));container.addEventListener('pointermove',e=>this.dragMove(e));container.addEventListener('pointerup',e=>this.dragEnd(e));container.addEventListener('pointercancel',()=>this.cancelDrag());this.render()}

 dragStart(e){const tile=e.target.closest('[data-piece]');if(!tile||e.button!==0)return;this.drag={piece:tile.dataset.piece,x:e.clientX,y:e.clientY,tile,pointer:e.pointerId,moved:false};tile.setPointerCapture(e.pointerId)}
 dragMove(e){if(!this.drag)return;const d=this.drag;if(!d.moved&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<7)return;e.preventDefault();d.moved=true;if(!d.ghost){d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.textContent=pieceLabel(d.piece);document.body.append(d.ghost);d.tile.classList.add('dragging')}d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop],[data-anchor]');if(d.target!==target){d.target?.classList.remove('drop-hover');d.target=target;target?.classList.add('drop-hover')}}
 dragEnd(e){if(!this.drag)return;const d=this.drag;if(d.moved){e.preventDefault();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop],[data-anchor]');this.ignoreClickUntil=Date.now()+350;this.activePiece=d.piece;this.cancelDrag();if(target&&this.container.contains(target))this.apply(target.dataset.anchor||target.dataset.drop)}else this.cancelDrag()}
 cancelDrag(){if(!this.drag)return;this.drag.ghost?.remove();this.drag.target?.classList.remove('drop-hover');this.drag.tile?.classList.remove('dragging');this.drag=null}
 get index(){return this.data.index||0}get step(){return this.q.steps?.[this.index]}get s(){return this.data.steps[this.index]??={graph:clone(this.step?.source||this.q.source||null),arrows:[],conditions:['',''],intermediate:null,solved:false}}
 save(){this.onSave?.({data:clone(this.data),needsReview:this.needsReview,completed:this.completed,at:Date.now()})}
 checkpoint(){this.history.push(clone(this.data));this.history=this.history.slice(-30);this.s.solved=false;this.completed=false;this.feedback=null}
 pieces(list){return `<div class="piece-tray" aria-label="${t('choosePiece')}">${list.map(p=>`<button class="piece ${this.activePiece===p?'selected':''}" draggable="false" data-piece="${esc(p)}" aria-pressed="${this.activePiece===p}">${esc(pieceLabel(p))}</button>`).join('')}</div>`}
 graph(g,interactive=true){const d=drawGraph(g,{interactive,labels:false});return `<svg class="lab-molecule" viewBox="0 0 720 350" role="group" aria-label="${pick('Reaction structure','反应结构','Structure réactionnelle')}">${d.markup}</svg>`}
 slots(){return `<p class="eyebrow">${t('conditions')}</p><div class="reagent-slots">${[0,1].map(i=>`<button class="reagent-slot" data-drop="slot:${i}"><span>${t(i?'stage2':'stage1')}</span><strong>${esc(this.s.conditions[i]?pieceLabel(this.s.conditions[i]):'')||t('dropHere')}</strong></button>`).join('')}</div>`}
 prompt(){const id=this.q.id;return ({'product-acyl':()=>pick('Select a fragment, then click the atom to replace. Make the product of SOCl2 treatment.','先选择基团，再点击要替换的原子，构建 SOCl2 处理后的产物。','Choisissez un fragment puis cliquez sur l’atome à remplacer pour former le produit de SOCl2.'),'product-reduction':()=>pick('Choose the final group and click the carboxyl carbon. Show the isolated product after LiAlH4 and water.','选择最终基团，再点击羧基碳，构建 LiAlH4 还原并水处理后的产物。','Choisissez le groupe final puis cliquez sur le carbone carboxylique après LiAlH4 et traitement aqueux.'),'reagents-carbonation':()=>pick('Place a reagent tile in each stage, in the correct order.','将试剂卡片按正确顺序放入反应和后处理位置。','Placez une carte de réactif dans chaque étape, dans le bon ordre.'),'mechanism-fischer':()=>pick('Click electron sources and destinations, then choose the immediate intermediate.','依次点击电子来源和终点，再选择本步即时中间体。','Cliquez sur l’origine et la destination des électrons, puis choisissez l’intermédiaire immédiat.'),'mechanism-hvz':()=>pick('Complete the paired arrows and select the intermediate. Keep track of the two bromines.','补齐成对箭头并选择中间体，注意区分两种位置的溴。','Complétez les flèches associées et choisissez l’intermédiaire, sans confondre les deux bromes.'),'synthesis-nitrile':()=>pick('Build the next group on the highlighted end of the chain, then place the reaction conditions.','在碳链末端构建下一步基团，再放置反应条件。','Construisez le groupe suivant à l’extrémité de la chaîne puis placez les conditions.')})[id]()}
 candidates(){const target=this.step.targets[0];if(this.q.id==='mechanism-fischer'){const wrong=clone(target);const oxygen=this.index===0?'M_O':'W_O';wrong.atoms.find(a=>a.id===oxygen).charge=0;const wrong2=clone(this.step.source);return [target,wrong,wrong2]}const wrong=clone(target);wrong.atoms.forEach(a=>a.charge=0);const wrong2=change(target,{removeAtoms:['E_BrAlpha']});return [wrong,target,wrong2]}
 render(){this.stopDemo();this.arrows?.destroy();this.arrows=null;const q=this.q,s=this.s;let task='';if(q.kind==='mechanism'){task=`<div class="mechanism-step-label"><span>↷ ${pick('Electron flow','电子转移','Flux d’électrons')}</span><span>${this.index+1} / ${q.steps.length}</span></div><div class="science-surface arrow-board"><div id="electron-area"></div><div class="mechanism-demo" aria-hidden="true"></div><div class="mechanism-product" aria-hidden="true"><span class="mechanism-product-label">${pick('Immediate intermediate','即时中间体','Intermédiaire immédiat')}</span>${moleculeSVG(this.step.targets[0])}</div></div><div class="arrow-caption"><span>${t('addArrow')}</span><strong id="lab-arrow-count">${s.arrows.length} / ${this.step.arrows[0].length} ${t('arrows')}</strong></div><div class="mechanism-playback"><button class="outline-button" data-lab="animate" ${s.solved||this.reveal?'':'disabled'}>▷ ${pick('Play this step','播放本步变化','Animer cette étape')}</button><button class="text-button" data-lab="edit-arrows" hidden>↶ ${pick('Back to drawing','返回箭头练习','Retour au dessin')}</button></div><h3 class="small-title">${t('intermediate')}</h3><div class="intermediate-grid">${this.candidates().map((g,i)=>`<button class="intermediate-choice ${s.intermediate===i?'selected':''}" data-candidate="${i}" aria-pressed="${s.intermediate===i}" aria-label="${t('intermediate')} ${i+1}"><span class="option-marker">${'ABC'[i]}</span>${moleculeSVG(g)}</button>`).join('')}</div>`}else if(q.kind==='reagents'){task=`<div class="reaction-given"><span>CH3CH2MgBr</span><span>→</span>${moleculeSVG(q.target)}</div>${this.pieces(['CO2, dry THF','H3O+ / water','H2O','NaBH4'])}${this.slots()}`}else{const list=q.id==='product-acyl'?['Cl','Br','OH','NH2']:q.id==='product-reduction'?['CH2OH','CHO','COOH']:this.index===0?['CN','OH','Br']:['COOH','CONH2','CHO'];task=`<div class="science-surface" data-drop="molecule">${this.graph(s.graph)}</div>${this.pieces(list)}<p class="instruction-line">${t('clickDrag')}</p>${q.kind==='synthesis'?this.pieces(this.index===0?['NaCN, DMF','H2O','H3O+ / water']:['hot aqueous HCl, reflux','NaOH, water, reflux','HCl, acidify','H2O'])+this.slots():''}`}
 this.container.innerHTML=`<div class="lab-top"><button class="text-button" data-lab="back">← ${t('visual')}</button><span class="mono">19 / ${q.number}</span></div><section class="lab-heading"><span class="eyebrow">${t('labMode')} · ${this.L(q.topic)}</span><h1>${this.L(q.title)}</h1><p>${this.prompt()}</p>${q.conditions?`<div class="condition-strip">${esc(this.L(q.conditions))}</div>`:''}</section>${q.steps?`<div class="frame-tabs">${q.steps.map((st,i)=>`<button class="${this.index===i?'active':''}" data-frame="${i}">${this.L(st.title)} ${this.data.steps[i]?.solved?'✓':''}</button>`).join('')}</div>`:''}<div class="lab-workspace">${task}</div><div class="lab-actions"><button class="outline-button" data-lab="undo">↶ ${t('undo')}</button><button class="outline-button" data-lab="hint">${t('hint')}</button><button class="solid-button" data-lab="check">${q.steps?t('checkStep'):t('check')}</button><button class="text-button" data-lab="reveal">${t('reveal')}</button>${q.steps&&this.index<q.steps.length-1?`<button class="outline-button" data-lab="next">${t('nextStep')} →</button>`:''}<button class="text-button" data-lab="reset">${t('reset')}</button></div>${this.hint?`<aside class="lab-feedback">${this.L(q.hints[this.index]||q.hints[0])}</aside>`:''}${this.feedback?`<aside class="lab-feedback ${this.feedback.correct?'good':'bad'}" role="status"><strong>${this.feedback.correct?t('correct'):t('tryAgain')}</strong><p>${this.feedback.message}</p></aside>`:''}${this.reveal?`<aside class="lab-feedback"><h3>${t('reveal')}</h3><p>${this.L(this.step?.answer||q.explanation)}</p>${moleculeSVG(this.step?.targets?.[0]||q.targets?.[0]||q.target)}</aside>`:''}<div class="reference-line">${t('source')} · ${q.refs.map(p=>`<button class="text-button" data-page="${p}">${t('page')} ${p} ↗</button>`).join('')}</div>`;
 if(q.kind==='mechanism')this.arrows=new ElectronCanvas(this.container.querySelector('#electron-area'),this.step.source,s.arrows,arr=>{this.checkpoint();s.arrows=arr;this.save();const play=this.container.querySelector('[data-lab=animate]');if(play)play.disabled=!s.solved&&!this.reveal;this.container.querySelector('.lab-feedback')?.remove();const n=this.container.querySelector('#lab-arrow-count');if(n)n.textContent=arr.length+' / '+this.step.arrows[0].length+' '+t('arrows')});if(this.arrows)this.arrows.svg.setAttribute('role','group');
 }
 apply(target){if(!this.activePiece)return;const piece=this.activePiece,s=this.s;this.checkpoint();if(target.startsWith('slot:')){const i=+target.slice(5);s.conditions[i]=piece}else{const atom=target.startsWith('atom:')?target.slice(5):null;if(!atom){this.history.pop();return}if(this.q.id==='product-acyl'){if(!['Cl','Br','OH','NH2'].includes(piece))return;const el={Cl:'Cl',Br:'Br',OH:'O',NH2:'N'}[piece];s.graph=change(s.graph,{atoms:{[atom]:{el,charge:0}}})}else if(this.q.id==='product-reduction'){if(!['CH2OH','CHO','COOH'].includes(piece)||!s.graph.atoms.some(a=>a.id===atom&&a.el==='C'))return;s.graph=change(s.graph,{removeAtoms:['O1','O2']});const c=s.graph.atoms.find(a=>a.id===atom);s.graph.atoms.push({id:'O1',el:'O',x:c.x+85,y:c.y+25,charge:0});s.graph.bonds.push({id:bondId(atom,'O1'),a:atom,b:'O1',order:piece==='CHO'?2:1});if(piece==='COOH'){s.graph.bonds[s.graph.bonds.length-1].order=2;s.graph.atoms.push({id:'O2',el:'O',x:c.x,y:c.y-90,charge:0});s.graph.bonds.push({id:bondId(atom,'O2'),a:atom,b:'O2',order:1})}}else if(this.q.kind==='synthesis'){if(this.index===0&&atom==='Br1'){if(piece==='CN')s.graph=clone(butanenitrile);else if(piece==='OH')s.graph=change(this.q.steps[0].source,{atoms:{Br1:{el:'O'}}});else if(piece==='Br')s.graph=clone(this.q.steps[0].source)}else if(this.index===1&&['N1','C4'].includes(atom)){if(piece==='COOH')s.graph=clone(butanoic);else if(piece==='CONH2')s.graph=change(butanoic,{atoms:{O2:{el:'N'}}});else if(piece==='CHO')s.graph=change(butanoic,{removeAtoms:['O2']})}else{this.history.pop();return}}}this.save();this.render()}
 click(e){if(Date.now()<(this.ignoreClickUntil||0))return;const tile=e.target.closest('[data-piece]');if(tile){this.activePiece=tile.dataset.piece;this.container.querySelectorAll('[data-piece]').forEach(n=>n.classList.toggle('selected',n.dataset.piece===this.activePiece));return}const frame=e.target.closest('[data-frame]');if(frame){this.data.index=+frame.dataset.frame;this.feedback=null;this.hint=false;this.reveal=false;this.activePiece=null;this.save();this.render();return}const candidate=e.target.closest('[data-candidate]');if(candidate){this.checkpoint();this.s.intermediate=+candidate.dataset.candidate;this.save();this.render();return}const page=e.target.closest('[data-page]');if(page){this.onRead?.(+page.dataset.page);return}const target=e.target.closest('[data-anchor],[data-drop]');if(target&&this.q.kind!=='mechanism'){this.apply(target.dataset.anchor||target.dataset.drop);return}const action=e.target.closest('[data-lab]')?.dataset.lab;if(!action)return;switch(action){case'animate':this.animateStep();return;case'edit-arrows':this.stopDemo();return;case'back':this.onBack?.();return;case'check':this.check();return;case'undo':this.stopDemo();if(this.q.kind==='mechanism'&&this.arrows?.history.length){this.arrows.undo();return}if(this.history.length){this.data=this.history.pop();this.completed=false;this.feedback=null;this.save();this.render()}return;case'hint':this.hint=true;this.needsReview=true;this.save();this.render();return;case'reveal':this.reveal=true;this.needsReview=true;this.save();this.render();return;case'next':this.data.index=Math.min(this.index+1,this.q.steps.length-1);this.hint=false;this.reveal=false;this.feedback=null;this.activePiece=null;this.save();this.render();return;case'reset':this.data={index:0,steps:{}};this.history=[];this.feedback=null;this.reveal=false;this.hint=false;this.needsReview=false;this.completed=false;this.activePiece=null;this.save();this.render();return}}
 check(){const s=this.s,q=this.q,step=this.step;let checks=[];if(q.kind==='mechanism'){checks.push(checkArrowSet(s.arrows,step.arrows));if(s.intermediate===null)checks.push({correct:false});else checks.push(compareGraphs(this.candidates()[s.intermediate],step.targets))}else if(q.kind==='reagents')checks.push(checkReagents(s.conditions,q.reagentKind));else{checks.push(compareGraphs(s.graph,step?.targets||q.targets));if(q.kind==='synthesis')checks.push(checkReagents(s.conditions,step.reagentKind))}const correct=checks.every(c=>c.correct);s.solved=correct;if(!correct)this.needsReview=true;this.completed=(q.steps||[{}]).every((_,i)=>this.data.steps[i]?.solved);this.feedback={correct,message:correct?this.L(step?.answer||q.explanation):q.kind==='mechanism'?t('bothArrows')+' '+t('intermediate'):pick('Recheck the reaction centre, carbon count, reagent order and final workup.','检查反应位置、碳数、试剂顺序与最终后处理。','Vérifiez le centre réactionnel, le nombre de carbones, l’ordre des réactifs et le traitement final.')};this.save();this.render();if(correct&&q.kind==='mechanism')this.animateStep()}
 animateStep(){if(this.q.kind!=='mechanism'||(!this.s.solved&&!this.reveal))return;this.stopDemo();const board=this.container.querySelector('.arrow-board'),demo=board.querySelector('.mechanism-demo'),product=board.querySelector('.mechanism-product');this.demoCanvas=new ElectronCanvas(demo,this.step.source,this.step.arrows[0],null);demo.querySelectorAll('.electron-arrow').forEach(p=>p.setAttribute('pathLength','1'));board.classList.add('is-playing');this.container.querySelector('#electron-area').inert=true;this.container.querySelector('[data-lab="edit-arrows"]').hidden=false;const reduced=document.body.classList.contains('reduce-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches;this.previewTimer=setTimeout(()=>{board.classList.add('show-product');product.setAttribute('aria-hidden','false');product.setAttribute('role','img');product.setAttribute('aria-label',pick('Immediate product of this elementary step','本基元步骤的即时产物','Produit immédiat de cette étape élémentaire'))},reduced?0:900)}
 stopDemo(){clearTimeout(this.previewTimer);this.demoCanvas?.destroy();this.demoCanvas=null;const board=this.container?.querySelector('.arrow-board');board?.classList.remove('is-playing','show-product');const source=this.container?.querySelector('#electron-area');if(source)source.inert=false;const product=board?.querySelector('.mechanism-product');product?.setAttribute('aria-hidden','true');const edit=this.container?.querySelector('[data-lab="edit-arrows"]');if(edit)edit.hidden=true}

 dispose(){this.stopDemo();this.cancelDrag();this.arrows?.destroy();this.container.removeEventListener('click',this.handle)}
}
